import React, { useState, useEffect } from 'react';
import { useStore } from '../../store/useStore';
import ResultView from './ResultView';

export default function MyResults({ navigate }) {
  var store = useStore();
  var [subs, setSubs] = useState([]);
  var [loading, setLoading] = useState(true);
  var [viewResult, setViewResult] = useState(null);

  useEffect(function() {
    store.loadSubmissions(store.currentUser.user_id).then(function(d) { setSubs(d); setLoading(false); });
  }, []); // eslint-disable-line

  if (viewResult) return React.createElement(ResultView, { submission: viewResult, onBack: function() { setViewResult(null); } });
  if (loading) return <div className="loading-center"><div className="spinner"></div></div>;

  return (
    <div className="fade-up">
      <div className="page-title" style={{ marginBottom: 24 }}>📊 My Results</div>
      {subs.length === 0 ? <div className="empty-state"><div className="empty-state-icon">📋</div><div className="empty-state-title">No exam results yet</div></div> : (
        <div>
          {subs.map(function(s) {
            var scorePct = s.total_marks > 0 ? Math.round((s.total_score / s.total_marks) * 100) : 0;
            return (
              <div key={s.submission_id} className="card" style={{ marginBottom: 12, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <div style={{ fontWeight: 600, fontSize: '1rem' }}>{s.title}</div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text3)', marginTop: 4 }}>
                    Score: {s.total_score || 0}/{s.total_marks} ({scorePct}%) • Status: {s.status}
                    {s.cheating_detected === 1 && <span style={{ color: 'var(--danger)', marginLeft: 8 }}>🚫 Cheating Detected</span>}
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                  <span className={'badge badge-' + (s.grade === 'A' ? 'success' : s.grade === 'F' ? 'danger' : 'warning')} style={{ fontSize: '1rem', padding: '6px 14px' }}>{s.grade || '-'}</span>
                  <button className="btn btn-outline btn-sm" onClick={function() { setViewResult(s); }}>View Details →</button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
